然后唤醒主会话去做"准备"（识别、入库、弹幕/元数据、摆给用户看）。

幂等：条目 id 记在 records/starport-seen.json，见过就不再重复处理或唤醒。
失败不抛异常给调度器，只记录并如实写进唤醒事实里。

环境变量：
  STARPORT_FEED   覆盖发布源地址（默认本机 54595 的 /rss；也接受本地文件路径）
  STARPORT_NO_WAKE 设为 1 时只巡查不唤醒（用于调试）
"""
import hashlib
import json
import os
import re
import subprocess
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FEED_URL = os.environ.get("STARPORT_FEED", "[redacted URL]")
STATE_FILE = ROOT / "records" / "starport-seen.json"
INBOX = ROOT / "records" / "starport-inbox"
LOG_FILE = ROOT / "logs" / "starport.log"
MAX_ITEMS = 50


def now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def log(message: str) -> None:
    line = f"{now_iso()} {message}"
    try:
        LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
        with LOG_FILE.open("a", encoding="utf-8") as handle:
            handle.write(line + "'"\\n\")
    except OSError:
        pass
    print(line)


def read_feed() -> bytes:
    \"\"\"抓取发布源；本地文件路径也接受，方便离线自测。\"\"\"
    parsed = urllib.parse.urlsplit(FEED_URL)
    if parsed.scheme in (\"\", \"file\"):
        path = Path(urllib.request.url2pathname(parsed.path)) if parsed.scheme else Path(FEED_URL)
        return path.expanduser().read_bytes()
    request = urllib.request.Request(FEED_URL, headers={\"User-Agent\": \"nipa-harness-starport/1\"})
    with urllib.request.urlopen(request, timeout=15) as response:
        return response.read()


def local_name(tag: str) -> str:
    return tag.rsplit(\"}\", 1)[-1].lower()


def text_of(element) -> str:
    return (element.text or \"\").strip() if element is not None else \"\"


def parse_items(xml_bytes: bytes) -> list:
    \"\"\"RSS 2.0 的 item 与 Atom 的 entry 都解析；字段缺失不报错。\"\"\"
    root = ET.fromstring(xml_bytes)
    items = []
    for node in root.iter():
        kind = local_name(node.tag)
        if kind not in (\"item\", \"entry\"):
            continue
        record = {\"title\": \"\", \"link\": \"\", \"published\": \"\", \"guid\": \"\",
                  \"enclosure\": \"\", \"enclosureType\": \"\", \"summary\": \"\"}
        for child in node:
            name = local_name(child.tag)
            if name == \"title\":
                record[\"title\"] = text_of(child)
            elif name == \"link\":
                record[\"link\"] = (child.get(\"href\") or text_of(child)).strip()
            elif name in (\"pubdate\", \"published\", \"updated\"):
                record[\"published\"] = record[\"published\"] or text_of(child)
            elif name in (\"guid\", \"id\"):
                record[\"guid\"] = record[\"guid\"] or text_of(child)
            elif name == \"enclosure\":
                record[\"enclosure\"] = (child.get(\"url\") or \"\").strip()
                record[\"enclosureType\"] = (child.get(\"type\") or \"\").strip()
            elif name == \"summary\" and not record[\"summary\"]:
                record[\"summary\"] = text_of(child)
            elif name == \"description\" and not record[\"summary\"]:
                record[\"summary\"] = text_of(child)
        if record[\"enclosure\"]:
            record[\"enclosure\"] = urllib.parse.urljoin(FEED_URL, record[\"enclosure\"])
        if not record[\"link\"] and record[\"guid\"].startswith(\"http\"):
            record[\"link\"] = record[\"guid\"]
        record[\"id\"] = item_id(record)
        items.append(record)
    items.reverse()  # 源通常新在前；按时间正序处理更符合直觉
    return items[:MAX_ITEMS]


def item_id(record: dict) -> str:
    basis = record[\"guid\"] or record[\"link\"] or record[\"enclosure\"]
    if not basis:
        basis = f'{record[\"title\"]}|{record[\"published\"]}'
    return hashlib.sha1(basis.encode(\"utf-8\")).hexdigest()[:16]


def load_state() -> dict:
    try:
        state = json.loads(STATE_FILE.read_text(encoding=\"utf-8\"))
    except (OSError, ValueError):
        return {\"seen\": {}, \"updatedAt\": None}
    if not isinstance(state, dict) or not isinstance(state.get(\"seen\"), dict):
        return {\"seen\": {}, \"updatedAt\": None}
    return state


def save_state(state: dict) -> None:
    state[\"updatedAt\"] = now_iso()
    STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = STATE_FILE.with_suffix(\".tmp\")
    tmp.write_text(json.dumps(state, ensure_ascii=False, indent=2, sort_keys=True), encoding=\"utf-8\")
    tmp.replace(STATE_FILE)


def safe_name(value: str, fallback: str = \"attachment\") -> str:
    cleaned = re.sub(r\"["'^'"\\w.\\-\\u4e00-\\u9fff]+\", \"_\", value or \"\").strip(\"._\")
    return cleaned[:80] or fallback


def fetch_attachment(item: dict) -> dict:
    \"\"\"取回附件到 records/starport-inbox/<id>/，返回结果事实。\"\"\"
    url = item[\"enclosure\"]
    if not url:
        return {\"status\": \"no_attachment\"}
    parsed = urllib.parse.urlsplit(url)
    name = safe_name(Path(urllib.parse.unquote(parsed.path)).name)
    if \".\" not in name:
        name = safe_name(item[\"title\"] or item[\"id\"]) + \".bin\"
    folder = INBOX / item[\"id\"]
    folder.mkdir(parents=True, exist_ok=True)
    target = folder / name
    try:
        request = urllib.request.Request(url, headers={\"User-Agent\": \"nipa-harness-starport/1\"})
        with urllib.request.urlopen(request, timeout=30) as response:
            payload = response.read()
        target.write_bytes(payload)
        return {
            \"status\": \"saved\",
            \"path\": str(target),
            \"bytes\": len(payload),
            \"contentType\": item[\"enclosureType\"],
        }
    except (urllib.error.URLError, OSError, ValueError) as exc:
        return {\"status\": \"failed\", \"path\": str(target), \"error\": f\"{type(exc).__name__}: {exc}\"}


def call_nipa(action: str, payload: dict) -> tuple:
    \"\"\"调用本机 NipaPlay；返回 (ok, 说明)。输入走临时文件，避免引号问题。\"\"\"
    with tempfile.NamedTemporaryFile(\"w\", suffix=\".json\", encoding=\"utf-8\", delete=False) as handle:
        json.dump(payload, handle, ensure_ascii=False)
        temp_path = handle.name
    try:
        completed = subprocess.run(
            [sys.executable, str(ROOT / \"nipa\"), \"call\", action, \"@\" + temp_path],
            capture_output=True, text=True, timeout=45, cwd=str(ROOT),
        )
    except subprocess.TimeoutExpired:
        return False, \"nipa call 超时\"
    finally:
        try:
            os.unlink(temp_path)
        except OSError:
            pass
    if completed.returncode "'!= 0:
        return False, (completed.stderr or completed.stdout or "nipa 调用失败").strip()[:500]
    try:
        reply = json.loads(completed.stdout)
    except ValueError:
        return False, completed.stdout.strip()[:500]
    if reply.get("status") != "completed":
        return False, json.dumps(reply.get("error", reply), ensure_ascii=False)[:500]
    return True, ""


def wake_agent(new_items: list) -> tuple:
    lines = []
    for entry in new_items:
        facts = entry["item"]
        note = entry["download"]
        piece = f'"'《{facts[\"title\"] or facts[\"id\"]}》'
        if facts[\"published\"]:
            piece += f'（{facts[\"published\"]}）'
        if note.get(\"status\") == \"saved\":
            piece += f'，附件已存到 {note[\"path\"]}（{note[\"bytes\"]} 字节）'
        elif note.get(\"status\") == \"no_attachment\":
            piece += \"，该条没有附件，只有链接\"
        else:
            piece += f'，附件取回失败：{note.get(\"error\")}'
        lines.append(piece)

    instruction = (
        \"《星港来信》发布源出现 \"
        f\"{len(new_items)} 个新条目，巡查脚本已取回能取回的附件。\"
        \"请完成准备：核对条目内容，把它变成 NipaPlay 里可用的形态\"
        \"（必要时放入媒体库/下载目录、补齐身份、元数据与弹幕），\"
