        \"instruction\": instruction,
        \"title\": \"《星港来信》有更新\",
        \"facts\": {
            \"feed\": FEED_URL,
            \"checkedAt\": now_iso(),
            \"count\": len(new_items),
            \"items\": [
                {
                    \"id\": entry[\"item\"][\"id\"],
                    \"title\": entry[\"item\"][\"title\"],
                    \"link\": entry[\"item\"][\"link\"],
                    \"published\": entry[\"item\"][\"published\"],
                    \"enclosure\": entry[\"item\"][\"enclosure\"],
                    \"download\": entry[\"download\"],
                }
                for entry in new_items
            ],
            \"summary\": lines,
        },
    })
    if not ok:
        log(f\"唤醒失败：{error}\")
    return ok, error


def main() -> int:
    if not sys.stdin.isatty():
        try:
            sys.stdin.read()
        except OSError:
