        return 0
    if not fresh:
        log(f\"没有新条目（源内 {len(items)} 条，均已见过）\")
        save_state(state)
        return 0

    handled = []
    for item in fresh:
        download = fetch_attachment(item)
        seen[item[\"id\"]] = {
            \"title\": item[\"title\"],
            \"published\": item[\"published\"],
            \"firstSeenAt\": now_iso(),
            \"download\": download,
        }
