        log(f'新条目《{item[\"title\"] or item[\"id\"]}》 附件={download.get(\"status\")}')

    save_state(state)

    if os.environ.get(\"STARPORT_NO_WAKE\") == \"1\":
        log(f\"发现 {len(handled)} 个新条目；STARPORT_NO_WAKE=1，未唤醒\")
        return 0

